import { chromium } from 'playwright'
import path from 'node:path'
const [file, out, w, h] = process.argv.slice(2)
const b = await chromium.launch()
const p = await b.newPage({ viewport: { width: +w, height: +(h || 1000) }, deviceScaleFactor: 1 })
await p.goto(new URL('file:///' + path.resolve(file).split(path.sep).join('/')).href, { waitUntil: 'load' })
await p.waitForTimeout(2500)
await p.screenshot({ path: out, fullPage: true })
await b.close()
console.log('wrote', out)

import fs from 'node:fs'
import { FLATS, PALETTES, flat } from './flats.mjs'
const names = Object.keys(FLATS)
const cells = names.map(n => `<figure>${flat(n, PALETTES.paper, 'width="200" height="260"')}<figcaption>${n}</figcaption></figure>`).join('')
const dark = names.map(n => `<figure class=d>${flat(n, PALETTES.ink, 'width="200" height="260"')}<figcaption>${n}</figcaption></figure>`).join('')
fs.writeFileSync('design/flats.html', `<style>
body{margin:0;background:#efe9dd;font:11px ui-monospace,monospace;color:#1a1a18;padding:16px}
.row{display:flex;flex-wrap:wrap;gap:12px}figure{margin:0;background:#fff;padding:8px}
figure.d{background:#14171c;color:#d9d2c4}figcaption{text-transform:uppercase;letter-spacing:.1em;margin-top:6px}
h2{font:11px ui-monospace,monospace;letter-spacing:.2em;text-transform:uppercase}
</style><h2>paper palette</h2><div class=row>${cells}</div><h2>ink palette</h2><div class=row style="background:#14171c;padding:12px">${dark}</div>`)

// Authored garment "flats" — technical drawings of the nine styles.
// Drawn, not photographed: they never imply a verified photograph of inventory.
// viewBox 0 0 200 300. c = { cloth, shade, ink }

const P = (d, extra = '') => `<path d="${d}" ${extra}/>`

// shared geometry -------------------------------------------------------
const BODY = 'M58 52 L66 104 L62 264 L138 264 L134 104 L142 52 Z'
const SLEEVE_L_LONG = 'M58 52 L28 66 L14 178 L46 190 L66 104 Z'
const SLEEVE_R_LONG = 'M142 52 L172 66 L186 178 L154 190 L134 104 Z'
const SLEEVE_L_SHORT = 'M58 52 L32 66 L24 122 L64 132 L66 104 Z'
const SLEEVE_R_SHORT = 'M142 52 L168 66 L176 122 L136 132 L134 104 Z'
const CUFF_L = 'M17 154 L49 166'
const CUFF_R = 'M183 154 L151 166'

const top = (c, { sleeves = 'long', body = BODY, neck = '', front = '', detail = '', buttons = [] } = {}) => `
  <g fill="${c.cloth}" stroke="${c.ink}" stroke-width="1.7" stroke-linejoin="round" stroke-linecap="round">
    ${P(sleeves === 'long' ? SLEEVE_L_LONG : SLEEVE_L_SHORT)}
    ${P(sleeves === 'long' ? SLEEVE_R_LONG : SLEEVE_R_SHORT)}
    ${P(body)}
    ${neck}
    ${front}
    <g fill="none">${sleeves === 'long' ? P(CUFF_L) + P(CUFF_R) : ''}${detail}</g>
    <g fill="${c.ink}" stroke="none">${buttons.map((y) => `<circle cx="95" cy="${y}" r="2.4"/>`).join('')}</g>
  </g>`

const placket = `<g fill="none"><path d="M100 62 L100 264"/><path d="M90 64 L90 264"/></g>`

export const FLATS = {
  // ---------- shirts ----------
  oxford: (c) =>
    top(c, {
      neck: P('M80 50 L100 74 L120 50 L126 40 L74 40 Z', `fill="${c.shade}"`),
      front: placket,
      detail: P('M66 124 h30 v34 h-30 z'),
      buttons: [88, 118, 148, 178, 208, 238],
    }),

  tee: (c) =>
    top(c, {
      sleeves: 'short',
      neck: `<g fill="none"><path d="M78 50 Q100 76 122 50"/><path d="M81 55 Q100 79 119 55"/></g>`,
      detail: P('M62 254 L138 254'),
    }),

  // ---------- outerwear ----------
  chore: (c) =>
    top(c, {
      neck: P('M76 48 L100 70 L124 48 L124 36 L76 36 Z', `fill="${c.shade}"`),
      front: placket,
      detail: `${P('M60 90 L140 90')}${P('M66 132 h30 v40 h-30 z')}${P('M106 132 h30 v40 h-30 z')}${P('M70 192 h28 v36 h-28 z')}`,
      buttons: [94, 126, 158, 190, 222, 252],
    }),

  overshirt: (c) =>
    top(c, {
      neck: P('M78 48 L100 72 L122 48 L130 38 L70 38 Z', `fill="${c.shade}"`),
      front: placket,
      detail: `${P('M66 138 h30 v7 h-30 z')}${P('M106 138 h30 v7 h-30 z')}${P('M62 250 L138 250')}`,
      buttons: [92, 128, 164, 200, 236],
    }),

  // ---------- knitwear ----------
  knit: (c) =>
    top(c, {
      body: 'M58 52 L66 104 L64 252 L136 252 L134 104 L142 52 Z',
      neck: P('M78 48 Q100 74 122 48 L122 38 Q100 62 78 38 Z', `fill="${c.shade}"`),
      detail:
        `<g opacity=".55">${P('M74 110 L74 240')}${P('M88 110 L88 240')}${P('M102 110 L102 240')}${P('M116 110 L116 240')}${P('M130 110 L130 240')}</g>` +
        P('M64 236 L136 236'),
    }),

  cardigan: (c) =>
    top(c, {
      neck: P('M74 46 L100 96 L126 46 L138 58 L112 112 L100 264 L88 112 L62 58 Z', `fill="${c.shade}"`),
      detail:
        `<g opacity=".5">${P('M72 120 L72 248')}${P('M82 126 L82 248')}${P('M118 126 L118 248')}${P('M128 120 L128 248')}</g>` +
        P('M62 252 L138 252'),
    }),

  // ---------- trousers ----------
  trouser: (c) => `
    <g fill="${c.cloth}" stroke="${c.ink}" stroke-width="1.7" stroke-linejoin="round">
      ${P('M52 30 L148 30 L146 60 L140 286 L108 286 L100 150 L92 286 L60 286 L54 60 Z')}
      ${P('M52 30 L148 30 L147 48 L53 48 Z', `fill="${c.shade}"`)}
      <g fill="none">
        ${P('M84 48 L90 190')}${P('M116 48 L110 190')}
        ${P('M100 48 L100 150')}
        ${P('M60 276 L92 276')}${P('M108 276 L140 276')}
        ${P('M58 56 q14 12 20 30')}${P('M142 56 q-14 12 -20 30')}
      </g>
      <g fill="${c.ink}" stroke="none"><circle cx="100" cy="39" r="2.4"/></g>
    </g>`,

  jean: (c) => `
    <g fill="${c.cloth}" stroke="${c.ink}" stroke-width="1.7" stroke-linejoin="round">
      ${P('M54 32 L146 32 L144 62 L138 288 L106 288 L100 154 L94 288 L62 288 L56 62 Z')}
      ${P('M54 32 L146 32 L145 50 L55 50 Z', `fill="${c.shade}"`)}
      <g fill="none" stroke-dasharray="4 3" opacity=".85">
        ${P('M68 58 h28 q0 24 -14 28 q-14 -4 -14 -28 z')}
        ${P('M104 58 h28 q0 24 -14 28 q-14 -4 -14 -28 z')}
        ${P('M100 50 L100 154')}
        ${P('M62 278 L94 278')}${P('M106 278 L138 278')}
        ${P('M55 50 L145 50')}
      </g>
      <g fill="${c.ink}" stroke="none"><circle cx="100" cy="41" r="2.3"/></g>
    </g>`,

  shorts: (c) => `
    <g fill="${c.cloth}" stroke="${c.ink}" stroke-width="1.7" stroke-linejoin="round">
      ${P('M50 60 L150 60 L148 90 L146 214 L106 214 L100 168 L94 214 L54 214 L52 90 Z')}
      ${P('M50 60 L150 60 L149 82 L51 82 Z', `fill="${c.shade}"`)}
      <g fill="none">
        ${P('M100 82 L100 168')}
        ${P('M54 204 L94 204')}${P('M106 204 L146 204')}
        ${P('M56 90 q12 10 16 26')}${P('M144 90 q-12 10 -16 26')}
        <g stroke-dasharray="3 3" opacity=".8">${P('M100 62 L100 80')}${P('M112 62 L112 80')}${P('M124 62 L124 80')}${P('M136 62 L136 80')}</g>
      </g>
      <g fill="${c.ink}" stroke="none"><circle cx="76" cy="71" r="2.3"/></g>
    </g>`,
}

export const PALETTES = {
  ink: { cloth: '#ded6c6', shade: '#c7bda9', ink: '#12151a' },
  paper: { cloth: '#f4eee2', shade: '#e3dbca', ink: '#1a1a18' },
}

export function flat(id, palette = PALETTES.paper, extra = '') {
  const draw = FLATS[id]
  if (!draw) return ''
  return `<svg viewBox="0 0 200 300" ${extra} xmlns="http://www.w3.org/2000/svg">${draw(palette)}</svg>`
}

import fs from 'node:fs'
import { flat, PALETTES } from './flats.mjs'
import { GARMENTS, SIZES, CATEGORIES, SIZE_CHART, CARE, SHIPPING, REVIEWS, ABOUT } from './content.mjs'

const F = (id, w = 260) => flat(id, PALETTES.ink, `width="${w}" height="${w * 1.5}"`)
const count = (c) => GARMENTS.filter((g) => g.category === c).length

const chips = (g) =>
  SIZES.map((s) => `<span class="chip${g.sold.includes(s) ? ' out' : ''}${s === 'M' && g.id === 'chore' ? ' on' : ''}">${s}</span>`).join('')

const card = (g) => `
<article class="card">
  <div class="plate">${F(g.id, 210)}<span class="plateno">${String(GARMENTS.indexOf(g) + 1).padStart(2, '0')}</span></div>
  <header><h3>${g.name}</h3><span class="price">£${g.price}</span></header>
  <p class="cat">${g.category}</p>
  <p class="detail">${g.detail}</p>
  <p class="fabric">${g.fabric}</p>
  <p class="colours">${g.colours.join(' · ')}</p>
  <div class="chips">${chips(g)}</div>
  <button class="add${g.id === 'chore' ? ' ready' : ''}">${g.id === 'chore' ? 'Add size M — £165' : 'Choose a size'}</button>
</article>`

const html = `<!doctype html><html><head><meta charset="utf-8">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@75..125,400..800&display=swap">
<style>
:root{--bg:#0f1216;--panel:#171c22;--cloth:#ded6c6;--ink:#12151a;--mut:#878d97;--acc:#c5462c;--line:#262c34}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--cloth);font-family:Archivo,system-ui,sans-serif;font-size:15px;line-height:1.55}
h1,h2,h3{margin:0;font-weight:700;font-stretch:112%;letter-spacing:-.02em;line-height:.92;text-transform:uppercase}
.k{font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:var(--mut);font-weight:600;font-stretch:100%}
.wrap{max-width:1280px;margin:0 auto;padding:0 40px}

/* ---- top bar ---- */
.bar{position:sticky;top:0;display:flex;align-items:center;justify-content:space-between;
  padding:16px 40px;border-bottom:1px solid var(--line);background:rgba(15,18,22,.9);z-index:9}
.bar nav{display:flex;gap:28px}
.brand{font-weight:800;font-stretch:118%;letter-spacing:.06em;text-transform:uppercase;font-size:17px}
.bagbtn{border:1px solid var(--cloth);border-radius:999px;padding:5px 14px;font-size:11px;letter-spacing:.18em;text-transform:uppercase}

/* ---- hero ---- */
.hero{position:relative;height:880px;display:grid;grid-template-columns:1fr 640px;align-items:end;
  gap:40px;padding:0 40px 56px;max-width:1360px;margin:0 auto;overflow:hidden}
.hero h1{font-size:132px;font-stretch:125%;letter-spacing:-.045em}
.hero h1 em{font-style:normal;color:var(--acc)}
.hero .lede{max-width:430px;color:var(--mut);margin:26px 0 0;font-size:17px}
.hero .cue{margin-top:44px;display:flex;align-items:center;gap:14px}
.hero .cue .rail{height:1px;width:170px;background:var(--line);position:relative}
.hero .cue .rail i{position:absolute;left:0;top:-1px;height:3px;width:38px;background:var(--acc)}
/* the cloth column: the object that persists all the way down the page */
.column{position:relative;height:820px;background:linear-gradient(180deg,#232932,#1a1f26);
  border-left:1px solid var(--line);border-right:1px solid var(--line);display:flex;align-items:center;justify-content:center}
.column:before{content:'';position:absolute;inset:0;background:
  repeating-linear-gradient(90deg,rgba(222,214,198,.05) 0 1px,transparent 1px 7px)}
.column svg{position:relative;filter:drop-shadow(0 40px 60px rgba(0,0,0,.6))}
.tag{position:absolute;left:0;bottom:34px;background:var(--cloth);color:var(--ink);
  padding:7px 14px;font-size:10px;letter-spacing:.2em;text-transform:uppercase;font-weight:700}

/* ---- unroll stage ---- */
.stage{border-top:1px solid var(--line);padding:70px 0 20px}
.frames{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;margin-top:34px}
.fr{position:relative;background:var(--panel);height:430px;overflow:hidden;display:flex;align-items:center;justify-content:center}
.fr svg{transition:none}
.fr.f1 svg{transform:scale(1)}
.fr.f2 svg{transform:scale(2.5) translate(6%,14%)}
.fr.f3 svg{transform:scale(1.5) translate(-12%,-8%)}
.fr b{position:absolute;top:14px;left:16px;font-size:11px;letter-spacing:.2em;color:var(--mut)}
.fr p{position:absolute;left:16px;right:16px;bottom:14px;margin:0;font-size:12.5px;color:var(--mut);line-height:1.4}
.scrub{margin-top:18px;display:flex;align-items:center;gap:16px}
.scrub .track{flex:1;height:2px;background:var(--line);position:relative}
.scrub .track i{position:absolute;height:2px;background:var(--acc);left:0;width:58%}
.scrub .track s{position:absolute;top:-4px;width:10px;height:10px;background:var(--acc);left:58%;transform:rotate(45deg)}

/* ---- handoff ---- */
.handoff{margin-top:72px;border-top:1px solid var(--line);padding-top:56px}
.split{display:grid;grid-template-columns:1fr 1fr 1fr;gap:2px;margin-top:30px;height:300px}
