// Self-host the three typefaces of the Plate & Press direction (latin subset only).
import fs from 'node:fs'
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/139.0.0.0 Safari/537.36'
const URL =
  'https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Roboto+Mono:wght@400;500' +
  '&family=Newsreader:ital,opsz,wght@0,6..72,300..500;1,6..72,300..500&display=swap'

const css = await (await fetch(URL, { headers: { 'user-agent': UA } })).text()
fs.mkdirSync('src/fonts', { recursive: true })

const blocks = css.split('@font-face').slice(1)
const out = []
for (const b of blocks) {
  if (!/unicode-range:\s*U\+0000-00FF/.test(b)) continue // latin only
  const fam = b.match(/font-family:\s*'([^']+)'/)[1]
  const style = b.match(/font-style:\s*(\w+)/)[1]
  const weight = b.match(/font-weight:\s*([\d ]+)/)[1].trim()
  const url = b.match(/url\((https[^)]+)\)/)[1]
  const name = `${fam.toLowerCase().replace(/\s+/g, '-')}-${style}-${weight.replace(/\s+/g, '-')}.woff2`
  const buf = Buffer.from(await (await fetch(url, { headers: { 'user-agent': UA } })).arrayBuffer())
  fs.writeFileSync('src/fonts/' + name, buf)
  out.push(`@font-face{font-family:'${fam}';font-style:${style};font-weight:${weight};font-display:swap;src:url('./fonts/${name}') format('woff2')}`)
  console.log(name, buf.length)
}
fs.writeFileSync('src/fonts.css', out.join('\n') + '\n')

// The press.
//
// A photograph is never shown as a photograph. It is sampled, auto-levelled and
// printed back onto the paper as ink dots. Scroll progress across the element
// drives the dot cell from coarse to fine, so the picture prints itself as you
// reach it.
//
// One owner per canvas. Cells are quantised to a short ladder so most frames are
// a repaint of an already-computed grid rather than a new sample.

const INK = [22, 21, 15]
const PAPER = [239, 233, 221]

// Coarse to fine. The floor stays at 3 so it always reads as print, never as a photo.
export const CELL_LADDER = [26, 20, 15, 11, 8, 6, 5, 4, 3]

const sourceCache = new Map()

/** Decode once per URL; every canvas using that photograph shares the bitmap. */
export function loadSource(src) {
  if (!sourceCache.has(src)) {
    sourceCache.set(
      src,
      new Promise((resolve, reject) => {
        const img = new Image()
        img.onload = () => resolve(img)
        img.onerror = reject
        img.src = src
      }),
    )
  }
  return sourceCache.get(src)
}

/**
 * Sample `img` into a cols x rows luminance grid, cover-cropped, auto-levelled.
 * Returned values are 0 (paper) .. 1 (full ink).
 */
function sample(img, cols, rows) {
  const off = document.createElement('canvas')
  off.width = cols
  off.height = rows
  const oc = off.getContext('2d', { willReadFrequently: true })
  const s = Math.max(cols / img.width, rows / img.height)
  oc.drawImage(img, (cols - img.width * s) / 2, (rows - img.height * s) / 2, img.width * s, img.height * s)
  const d = oc.getImageData(0, 0, cols, rows).data

  const lum = new Float32Array(cols * rows)
  let lo = 1
  let hi = 0
  for (let k = 0; k < lum.length; k++) {
    const i = k * 4
    const v = (0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2]) / 255
    lum[k] = v
    if (v < lo) lo = v
    if (v > hi) hi = v
  }
  const span = Math.max(0.001, hi - lo)
  // Auto-level, then lift the midtones so ink never floods a whole area solid.
  for (let k = 0; k < lum.length; k++) lum[k] = Math.pow((lum[k] - lo) / span, 0.62)
  return lum
}

/**
 * A press for one canvas element. `print(progress)` is idempotent and cheap to
 * call every frame; it only redraws when the quantised cell actually changes.
 */
export function createPress(canvas, src) {
  let img = null
  let gridCache = new Map() // cell -> { cols, rows, lum }
  let lastKey = ''
  let cssW = 0
  let cssH = 0
  let disposed = false

  const dpr = () => Math.min(window.devicePixelRatio || 1, 2)

  function measure() {
    const r = canvas.getBoundingClientRect()
    if (!r.width || !r.height) return false
    const w = Math.round(r.width)
    const h = Math.round(r.height)
    if (w === cssW && h === cssH) return true
    cssW = w
    cssH = h
    // Cap the backing store: dots are big, resolution beyond this buys nothing.
    const scale = Math.min(dpr(), 1400 / Math.max(1, w))
    canvas.width = Math.round(w * scale)
    canvas.height = Math.round(h * scale)
    gridCache = new Map()
    lastKey = ''
    return true
  }

  function print(progress) {
    if (disposed || !img) return
    if (!measure()) return
    const t = Math.max(0, Math.min(1, progress))
    const idx = Math.min(CELL_LADDER.length - 1, Math.round(t * (CELL_LADDER.length - 1)))
    const key = idx + ':' + canvas.width
    if (key === lastKey) return
    lastKey = key

    const scale = canvas.width / cssW
    const cell = CELL_LADDER[idx] * scale
    const cols = Math.max(1, Math.ceil(canvas.width / cell))
    const rows = Math.max(1, Math.ceil(canvas.height / cell))

    let grid = gridCache.get(idx)
    if (!grid) {
      grid = { cols, rows, lum: sample(img, cols, rows) }
      gridCache.set(idx, grid)
    }

    const ctx = canvas.getContext('2d')
    ctx.fillStyle = `rgb(${PAPER.join(',')})`
    ctx.fillRect(0, 0, canvas.width, canvas.height)
    ctx.fillStyle = `rgb(${INK.join(',')})`
    const half = cell / 2
    const rMax = cell * 0.6
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const r = Math.sqrt(1 - Math.min(1, grid.lum[y * cols + x])) * rMax
        if (r < 0.25) continue
        ctx.beginPath()
        ctx.arc(x * cell + half, y * cell + half, r, 0, Math.PI * 2)
        ctx.fill()
      }
    }
    return CELL_LADDER[idx]
  }

  const ready = loadSource(src).then((loaded) => {
    img = loaded
    return true
  })

  return {
    ready,
    print,
    dispose() {
      disposed = true
      gridCache = new Map()
    },
  }
}

import { useEffect, useRef, useState } from 'react'
import { createPress } from './halftone'

// One rAF loop and one scroll listener for the whole page, no matter how many
// plates are on it. Presses register themselves; only the ones intersecting the
// viewport are asked to print.
const live = new Set()
let frame = 0

function tick() {
  frame = 0
  for (const entry of live) entry.run()
}

function schedule() {
  if (!frame) frame = requestAnimationFrame(tick)
}

let listening = false
function listen() {
  if (listening) return
  listening = true
  addEventListener('scroll', schedule, { passive: true })
  addEventListener('resize', schedule, { passive: true })
}

export const prefersReducedMotion = () =>
  typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * A photograph printed as halftone. `lead` is how far up the viewport the
 * element must travel before it is fully printed — the "fold".
 */
export default function Halftone({ src, alt, lead = 0.55, className = '', onProgress }) {
  const ref = useRef(null)
  const [state, setState] = useState({ pct: 0, cell: null })

  useEffect(() => {
    const canvas = ref.current
    if (!canvas) return
    const press = createPress(canvas, src)
    const reduced = prefersReducedMotion()
    let visible = false
    let last = -1

    const entry = {
      run() {
        if (!visible && last >= 0) return
        const r = canvas.getBoundingClientRect()
        const vh = innerHeight || 1
        // 0 when the top edge is at the bottom of the viewport,
        // 1 once it has travelled `lead` of the way up.
        const raw = (vh - r.top) / Math.max(1, vh * lead)
        const p = reduced ? 1 : Math.max(0, Math.min(1, raw))
        if (Math.abs(p - last) < 0.01 && last >= 0) return
        last = p
        const cell = press.print(p)
        if (cell !== undefined) {
          setState({ pct: Math.round(p * 100), cell })
          onProgress?.(p)
        }
      },
    }

    const io = new IntersectionObserver(
      ([e]) => {
        visible = e.isIntersecting
        if (visible) {
          live.add(entry)
          schedule()
        } else {
          live.delete(entry)
        }
      },
      { rootMargin: '150px 0px' },
    )

    press.ready.then(() => {
      io.observe(canvas)
      listen()
      entry.run()
    })

    return () => {
      io.disconnect()
      live.delete(entry)
      press.dispose()
    }
  }, [src, lead, onProgress])

  return (
    <canvas
      ref={ref}
      className={'halftone ' + className}
      role="img"
      aria-label={alt}
      data-pct={state.pct}
      data-cell={state.cell ?? ''}
    />
  )
}

// Registration.
//
// The sheet does not fade when you filter it. It re-registers: the plates that
// survive travel to their new cells, the way a forme is re-locked. Same idea for
// lifting a plate off the sheet into the enlarged view.
//
// Rects are measured on every run rather than cached, so a resize or an
// interrupted run always resolves to the current layout.

const EASE = 'cubic-bezier(.22,.61,.36,1)'

export function measure(nodes) {
  const map = new Map()
  for (const [key, node] of nodes) {
    if (!node) continue
    const r = node.getBoundingClientRect()
    if (r.width) map.set(key, r)
  }
  return map
}

/**
 * Invert-then-play. `before` is a Map(key -> DOMRect) captured before the layout
 * change; `nodes` is the same keyed map of elements after it.
 */
export function playRegistration(before, nodes, { duration = 420 } = {}) {
  const runs = []
  for (const [key, node] of nodes) {
    if (!node) continue
    const from = before.get(key)
    if (!from) {
      // A plate that was not on the sheet a moment ago: set it, don't slide it.
      runs.push(
        node.animate([{ opacity: 0 }, { opacity: 1 }], { duration: duration * 0.7, easing: EASE, fill: 'none' }),
      )
      continue
    }
    const to = node.getBoundingClientRect()
    const dx = from.left - to.left
    const dy = from.top - to.top
    if (Math.abs(dx) < 1 && Math.abs(dy) < 1) continue
    runs.push(
      node.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }], {
        duration,
        easing: EASE,
        fill: 'none',
      }),
    )
  }
  return runs
}

/**
 * Lift: the enlarged plate starts life at the rect of the sheet cell it came
 * from, so the garment you chose is visibly the garment you get.
 */
export function playLift(node, fromRect, { duration = 480 } = {}) {
  if (!node || !fromRect) return null
  const to = node.getBoundingClientRect()
  if (!to.width || !fromRect.width) return null
  const sx = fromRect.width / to.width
  const sy = fromRect.height / to.height
  const dx = fromRect.left + fromRect.width / 2 - (to.left + to.width / 2)
  const dy = fromRect.top + fromRect.height / 2 - (to.top + to.height / 2)
  return node.animate(
    [
      { transform: `translate(${dx}px, ${dy}px) scale(${sx}, ${sy})`, opacity: 0.55 },
      { transform: 'none', opacity: 1 },
    ],
    { duration, easing: EASE, fill: 'none' },
  )
}

